FROM public."Tool_Catalog" AS previous
JOIN (VALUES
    ('get_dimension_values', 'v2', 'v3', '{"additionalProperties":false,"properties":{"column":{"description":"A groupable text column of that table (not its entity column).","type":"string"},"match":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"Case-insensitive part of the value you look for (e.g. a word from the request), or null for every value."},"table":{"description":"A static catalog table (no time column), e.g. a reference table of classifications.","type":"string"}},"required":["table","column","match"],"type":"object"}',
     'List the exact stored values of one category column (a groupable text column of a static catalog table), optionally only those containing match. An entity column (tickers, broker codes) or a dated table is refused: find an entity''s code with search_values. Use it to write a scope predicate or a grouping key with the exact data value (for example the stored spelling of a classification the user named). Returns values only, at most 200, never counts or measures: it is not a data answer.')
) AS next(name, from_version, version, input_schema, purpose)
  ON previous.tool_name = next.name AND previous.version = next.from_version;

INSERT INTO public."Tool_Catalog" (
